// src/components/KnowYourCandidate.js
import React, { useState } from 'react';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [constituency, setConstituency] = useState(user?.constituency || '');

  const GEMINI_API_KEY = "AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE";
  const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`;

  const fetchCandidateInfo = async () => {
    if (!constituency) {
      setError(language === "hindi"
        ? "कृपया पहले अपना निर्वाचन क्षेत्र चुनें।"
        : "Please select your constituency first."
      );
      return;
    }

    setLoading(true);
    setError('');
    setCandidateInfo(null);

    try {
      const prompt = `
        Provide detailed, factual, and updated information about the 2024 Indian Lok Sabha election candidates 
        for the "${constituency}" constituency.
        
        Include for each candidate:
        - Full name (Hindi + English)
        - Political party
        - Education
        - Political experience
        - 3-4 main promises or manifesto points
        - Contact (Twitter, website, or email if known)

        Format response in valid JSON like this:
        [
          {
            "name": "Rahul Gandhi / राहुल गांधी",
            "party": "Indian National Congress / भारतीय राष्ट्रीय कांग्रेस",
            "education": "M.Phil. from Trinity College, Cambridge",
            "experience": "MP from Wayanad, Former Congress President",
            "promises": [
              "Focus on employment generation",
              "Support for small businesses",
              "Investment in education and healthcare"
            ],
            "contact": "@RahulGandhi"
          }
        ]
      `;

      const response = await fetch(GEMINI_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: {
            temperature: 0.4,
            topK: 40,
            topP: 0.9,
            maxOutputTokens: 1500,
          },
        }),
      });

      const data = await response.json();

      if (!response.ok) throw new Error(data.error?.message || 'AI request failed');

      const aiText = data.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
      console.log("Raw AI response:", aiText);

      // Clean markdown and parse JSON
      let cleanText = aiText.replace(/```json|```/g, '').trim();
      const jsonStart = cleanText.indexOf('[');
      const jsonEnd = cleanText.lastIndexOf(']') + 1;

      if (jsonStart === -1 || jsonEnd === -1)
        throw new Error('Invalid AI response (no JSON found)');

      const jsonString = cleanText.substring(jsonStart, jsonEnd);
      const candidates = JSON.parse(jsonString);

      const filtered = searchQuery
        ? candidates.filter(c =>
            (c.name && c.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
            (c.party && c.party.toLowerCase().includes(searchQuery.toLowerCase()))
          )
        : candidates;

      setCandidateInfo(filtered);
    } catch (err) {
      console.error("Gemini AI error:", err);
      setError(
        language === "hindi"
          ? `AI डेटा प्राप्त करने में त्रुटि: ${err.message}`
          : `Error fetching AI data: ${err.message}`
      );
    } finally {
      setLoading(false);
    }
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      selectConstituency: "अपना निर्वाचन क्षेत्र चुनें",
      searchPlaceholder: "उम्मीदवार या पार्टी खोजें...",
      searchButton: "खोजें",
      loading: "AI डेटा लोड हो रहा है...",
      fetchButton: "जानकारी प्राप्त करें",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      experience: "राजनीतिक अनुभव",
      promises: "वादे",
      contact: "संपर्क",
      aiPowered: "यह जानकारी Google Gemini AI द्वारा प्रदान की गई है",
      noCandidates: "कोई उम्मीदवार नहीं मिले"
    },
    english: {
      title: "Know Your Candidate",
      selectConstituency: "Select Constituency",
      searchPlaceholder: "Search candidate or party...",
      searchButton: "Search",
      loading: "Loading AI data...",
      fetchButton: "Get Candidate Info",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      experience: "Political Experience",
      promises: "Promises",
      contact: "Contact",
      aiPowered: "This information is provided by Google Gemini AI",
      noCandidates: "No candidates found"
    }
  };

  const t = translations[language];

  const constituencies = [
    "Amethi", "Rae Bareli", "Varanasi", "Lucknow", "Kanpur",
    "Delhi South", "Mumbai North", "Bangalore South", "Chennai Central",
    "Hyderabad", "Kolkata North", "Ahmedabad East", "Pune", "Jaipur"
  ];

  return (
    <div className="know-your-candidate">
      <h2>{t.title}</h2>

      <select value={constituency} onChange={(e) => setConstituency(e.target.value)}>
        <option value="">{t.selectConstituency}</option>
        {constituencies.map((c, i) => (
          <option key={i} value={c}>{c}</option>
        ))}
      </select>

      <input
        type="text"
        placeholder={t.searchPlaceholder}
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
      />

      <button onClick={fetchCandidateInfo} disabled={!constituency || loading}>
        {loading ? t.loading : t.fetchButton}
      </button>

      {error && <p className="error">{error}</p>}

      {candidateInfo && (
        <div className="candidate-list">
          <h3>{t.candidateInfo}</h3>
          {candidateInfo.length === 0 ? (
            <p>{t.noCandidates}</p>
          ) : (
            candidateInfo.map((c, i) => (
              <div key={i} className="candidate-card">
                <h4>{c.name}</h4>
                <p><b>{t.party}:</b> {c.party}</p>
                <p><b>{t.education}:</b> {c.education}</p>
                <p><b>{t.experience}:</b> {c.experience}</p>
                {c.promises && (
                  <ul>
                    {c.promises.map((p, j) => (
                      <li key={j}>✅ {p}</li>
                    ))}
                  </ul>
                )}
                {c.contact && <p><b>{t.contact}:</b> {c.contact}</p>}
              </div>
            ))
          )}
          <p className="ai-note">🤖 {t.aiPowered}</p>
        </div>
      )}
    </div>
  );
};

export default KnowYourCandidate;
